(()=>{
 const en=document.documentElement.lang==='en',reduced=matchMedia('(prefers-reduced-motion: reduce)');
 document.querySelectorAll('.showroom').forEach(root=>{
 const slides=[...root.querySelectorAll('.showroom-slide')],dots=[...root.querySelectorAll('[data-scene]')],stage=root.querySelector('.showroom-stage'),play=root.querySelector('[data-play]');
 let index=0,paused=false,hover=false,focus=false,visible=false,elapsed=0,last=0;
 const motion=()=>!reduced.matches&&window.paMotion!==false&&!document.body.classList.contains('no-motion');
 function label(){play.textContent=paused||!motion()?(en?'▶ Play':'▶ Авто'):(en?'Ⅱ Pause':'Ⅱ Пауза');play.setAttribute('aria-pressed',String(!paused&&motion()))}
 function media(){slides.forEach((s,i)=>s.querySelectorAll('video').forEach(v=>{if(i===index&&visible&&motion()&&!paused){if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{})}else v.pause()}))}
 function loadMedia(){if(!visible)return;for(const i of [index,(index+1)%slides.length])slides[i]?.querySelectorAll('img[data-src]').forEach(im=>{if(im.dataset.srcset)im.srcset=im.dataset.srcset;im.src=im.dataset.src;im.loading='eager';delete im.dataset.src;delete im.dataset.srcset})}
 function show(n,manual=false){index=(n+slides.length)%slides.length;elapsed=0;slides.forEach((s,i)=>{s.classList.toggle('active',i===index);s.classList.toggle('before',i===(index-1+slides.length)%slides.length);s.classList.toggle('after',i===(index+1)%slides.length);s.inert=i!==index;s.setAttribute('aria-hidden',String(i!==index));s.classList.remove('expanded');s.querySelector('[data-more]')?.setAttribute('aria-expanded','false')});dots.forEach((b,i)=>b.setAttribute('aria-current',String(i===index)));root.style.setProperty('--scene',slides[index].dataset.color);root.style.setProperty('--progress',0);root.querySelector('.scene-status').textContent=String(index+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');loadMedia();document.dispatchEvent(new CustomEvent('pa:showroom',{detail:{root,index}}));media();if(manual)document.dispatchEvent(new Event('pa:scene'))}
 root.classList.add('enhanced');root.querySelector('[data-prev]').onclick=()=>show(index-1,true);root.querySelector('[data-next]').onclick=()=>show(index+1,true);dots.forEach((b,i)=>b.onclick=()=>show(i,true));play.onclick=()=>{paused=!paused;label();media()};
 slides.forEach(s=>s.querySelector('[data-more]')?.addEventListener('click',e=>{const expanded=s.classList.toggle('expanded');e.currentTarget.setAttribute('aria-expanded',String(expanded));paused=true;label()}));
 root.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')hover=true});root.addEventListener('pointerleave',()=>hover=false);root.addEventListener('focusin',()=>focus=true);root.addEventListener('focusout',e=>focus=root.contains(e.relatedTarget));
 root.addEventListener('keydown',e=>{if(e.target.tagName==='VIDEO')return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1),true)}});
 let x=0,y=0,swiped=false;stage.addEventListener('touchstart',e=>{x=e.touches[0].clientX;y=e.touches[0].clientY;swiped=false},{passive:true});stage.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x,dy=e.changedTouches[0].clientY-y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.4){swiped=true;show(index+(dx<0?1:-1),true)}},{passive:true});stage.addEventListener('click',e=>{if(swiped){e.preventDefault();e.stopPropagation();swiped=false}},true);
 if('IntersectionObserver'in window)new IntersectionObserver(es=>{visible=es[0].isIntersecting;loadMedia();media()},{rootMargin:'250px',threshold:0}).observe(root);else visible=true;
 function tick(t){const dt=last?Math.min(t-last,100):0;last=t;if(visible&&!paused&&!hover&&!focus&&!document.hidden&&motion()){elapsed+=dt;root.style.setProperty('--progress',elapsed/4000);if(elapsed>=4000)show(index+1)}requestAnimationFrame(tick)}
 reduced.addEventListener('change',()=>{label();media()});document.getElementById('motion')?.addEventListener('click',()=>{label();media()});document.addEventListener('visibilitychange',()=>{if(document.hidden)slides.forEach(s=>s.querySelectorAll('video').forEach(v=>v.pause()));else media()});show(0);label();requestAnimationFrame(tick);
 });
 document.querySelectorAll('.case-collection video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==v)other.pause()})));
})();
